struct ShopAccess {
    static bool LoadItems(const std::string& path, Items& out, std::string& error) {
        std::string text;
        nlohmann::json doc;
        if (!canon::json::ReadFile(path, text, error)) return false;
        if (!canon::json::ParseDataFile(path, text, kItemsSchema, doc, error)) return false;
        canon::json::Decoder dec(path);
        const nlohmann::json* rows = dec.Array(doc, "rows");
        if (rows == nullptr) return error = dec.Error(), false;
        std::vector<Item> values(rows->size());
        std::vector<std::string> keys(rows->size());
        for (size_t i = 0; i < rows->size(); ++i) {
            dec.Push("rows[" + std::to_string(i) + "]");
            dec.String((*rows)[i], "$id", values[i].id_);
            if (const nlohmann::json* retired = dec.Optional((*rows)[i], "$retired")) {
                dec.AsBool(*retired, "$retired", values[i].retired_);
            }
            Decode((*rows)[i], dec, values[i]);
            dec.Pop();
            if (!dec.Ok()) return error = dec.Error(), false;
            keys[i] = values[i].id_;
            out.byCodeKeys_.push_back(values[i].code_);
        }
        out.rows_ = canon::KeyedList<std::string, Item>::FromRows(std::move(values), std::move(keys));
        out.byCode_ = canon::detail::SortedIndex(out.byCodeKeys_);
        return true;
    }

    static bool LoadShelves(const std::string& path, Shelves& out, std::string& error) {
        std::string text;
        nlohmann::json doc;
        if (!canon::json::ReadFile(path, text, error)) return false;
        if (!canon::json::ParseDataFile(path, text, kShelvesSchema, doc, error)) return false;
        canon::json::Decoder dec(path);
        const nlohmann::json* rows = dec.Array(doc, "rows");
        if (rows == nullptr) return error = dec.Error(), false;
        std::vector<Shelf> values(rows->size());
        std::vector<std::string> keys(rows->size());
        for (size_t i = 0; i < rows->size(); ++i) {
            dec.Push("rows[" + std::to_string(i) + "]");
            Decode((*rows)[i], dec, values[i]);
            dec.Pop();
            if (!dec.Ok()) return error = dec.Error(), false;
            keys[i] = values[i].id_;
            out.byDeleteKeys_.push_back(values[i].delete_);
            out.byIKeys_.push_back(values[i].i_);
        }
        out.rows_ = canon::KeyedList<std::string, Shelf>::FromRows(std::move(values), std::move(keys));
        out.byDelete_ = canon::detail::SortedIndex(out.byDeleteKeys_);
        out.byI_ = canon::detail::SortedIndex(out.byIKeys_);
        for (size_t i = 0; i < out.rows_.Len(); ++i) {
            dec.Push("rows[" + std::to_string(i) + "]");
            if (!Resolve(const_cast<Shelf&>(out.rows_.At(i)), out, dec)) return error = dec.Error(), false;
            dec.Pop();
        }
        return true;
    }

    static bool LoadConfig(const std::string& path, Config& out, std::string& error) {
        std::string text;
        nlohmann::json doc;
        if (!canon::json::ReadFile(path, text, error)) return false;
        if (!canon::json::ParseDataFile(path, text, kConfigSchema, doc, error)) return false;
        canon::json::Decoder dec(path);
        const nlohmann::json* value = dec.Required(doc, "value");
        if (value == nullptr) return error = dec.Error(), false;
        dec.Push("value");
        Decode(*value, dec, out);
        dec.Pop();
        if (!dec.Ok()) return error = dec.Error(), false;
        return true;
    }

    static bool LoadHome(const std::string& path, Point& out, std::string& error) {
        std::string text;
        nlohmann::json doc;
        if (!canon::json::ReadFile(path, text, error)) return false;
        if (!canon::json::ParseDataFile(path, text, kHomeSchema, doc, error)) return false;
        canon::json::Decoder dec(path);
        const nlohmann::json* value = dec.Required(doc, "value");
        if (value == nullptr) return error = dec.Error(), false;
        dec.Push("value");
        Decode(*value, dec, out);
        dec.Pop();
        if (!dec.Ok()) return error = dec.Error(), false;
        return true;
    }

    static std::shared_ptr<const ShopSnapshot> LoadSnapshot(const std::string& dir, std::string& error) {
        auto snap = std::make_shared<ShopSnapshot>();
        if (!LoadItems(dir + "/items.json", snap->items_, error)) return nullptr;
        if (!LoadConfig(dir + "/config.json", snap->config_, error)) return nullptr;
        {
            canon::json::Decoder dec(dir + "/items.json");
            for (size_t i = 0; i < snap->items_.rows_.Len(); ++i) {
                dec.Push("rows[" + std::to_string(i) + "]");
                if (!Resolve(const_cast<Item&>(snap->items_.rows_.At(i)), *snap, dec)) return error = dec.Error(), nullptr;
                dec.Pop();
            }
        }
        {
            canon::json::Decoder dec(dir + "/config.json");
            dec.Push("value");
            if (!Resolve(snap->config_, *snap, dec)) return error = dec.Error(), nullptr;
            dec.Pop();
        }
        return snap;
    }

    static bool Resolve(Item& x, const ShopSnapshot& ctx, canon::json::Decoder& dec) {
        if ((x.best_ref_ = ctx.items_.rows_.Find(x.best_)) == nullptr) return dec.Fail("$best", "no entry " + std::string(x.best_)), false;
        if (x.related_) {
            auto& refs = x.related_ref_.emplace();
            for (size_t i = 0; i < (*x.related_).size(); ++i) {
                const auto* e = ctx.items_.rows_.Find((*x.related_)[i]);
                if (e == nullptr) return dec.Fail("$related[" + std::to_string(i) + "]", "no entry " + std::string((*x.related_)[i])), false;
                refs.push_back(e);
            }
        }
        for (size_t c = 0; c < 4; ++c) {
            if (x.pairFor_[c] && (x.pairFor_ref_[c] = ctx.items_.rows_.Find(*x.pairFor_[c])) == nullptr) return dec.Fail("$pairFor", "no entry " + std::string(*x.pairFor_[c])), false;
        }
        return true;
    }

    static bool Resolve(Shelf& x, const Shelves& ctx, canon::json::Decoder& dec) {
        if (x.next_ && (x.next_ref_ = ctx.rows_.Find(*x.next_)) == nullptr) return dec.Fail("next", "no entry " + std::string(*x.next_)), false;
        return true;
    }

    static bool Resolve(BadgeStar& x, const ShopSnapshot& ctx, canon::json::Decoder& dec) {
        if ((x.of_ref_ = ctx.items_.rows_.Find(x.of_)) == nullptr) return dec.Fail("of", "no entry " + std::string(x.of_)), false;
        return true;
    }

    static bool Resolve(Badge& x, const ShopSnapshot& ctx, canon::json::Decoder& dec) {
        if (auto* c = std::get_if<0>(&x.value_); c != nullptr && !Resolve(*c, ctx, dec)) return false;
        return true;
    }

    static bool Resolve(Node& x, const ShopSnapshot& ctx, canon::json::Decoder& dec) {
        if (x.hot_ && (x.hot_ref_ = ctx.items_.rows_.Find(*x.hot_)) == nullptr) return dec.Fail("hot", "no entry " + std::string(*x.hot_)), false;
        if (x.next_) {
            dec.Push("next");
            if (!Resolve((*x.next_), ctx, dec)) return false;
            dec.Pop();
        }
        for (size_t i2 = 0; i2 < x.kids_.size(); ++i2) {
            dec.Push("kids[" + std::to_string(i2) + "]");
            if (!Resolve(x.kids_[i2], ctx, dec)) return false;
            dec.Pop();
        }
        if (x.badge_) {
            dec.Push("badge");
            if (!Resolve((*x.badge_), ctx, dec)) return false;
            dec.Pop();
        }
        return true;
    }

    static bool Resolve(Config& x, const ShopSnapshot& ctx, canon::json::Decoder& dec) {
        if ((x.featured_ref_ = ctx.items_.rows_.Find(x.featured_)) == nullptr) return dec.Fail("featured", "no entry " + std::string(x.featured_)), false;
        for (size_t i = 0; i < x.picks_.size(); ++i) {
            const auto* e = ctx.items_.rows_.Find(x.picks_[i]);
            if (e == nullptr) return dec.Fail("picks[" + std::to_string(i) + "]", "no entry " + std::string(x.picks_[i])), false;
            x.picks_ref_.push_back(e);
        }
        if (x.alts_) {
            auto& refs = x.alts_ref_.emplace();
            for (size_t i = 0; i < (*x.alts_).size(); ++i) {
                const auto* e = ctx.items_.rows_.Find((*x.alts_)[i]);
                if (e == nullptr) return dec.Fail("alts[" + std::to_string(i) + "]", "no entry " + std::string((*x.alts_)[i])), false;
                refs.push_back(e);
            }
        }
        dec.Push("tree");
        if (!Resolve(x.tree_, ctx, dec)) return false;
        dec.Pop();
        return true;
    }
};

